#nullable enable // autogenerated

using System.Collections.Generic;

namespace MVZ2.Resources
{
    public class LookupResourceResolver<TResource> : ResourceResolverTags<ResourceLookupKey, TResource>
    {
        protected override List<ResourceLookupKey> BuildCandidateKeys(ResourceLookupKey key, ResourceContext context)
        {
            var reference = key.id;
            var tagCandidates = GetTagCandidates(context);
            var list = new List<ResourceLookupKey>();
            foreach (var candidate in tagCandidates)
            {
                list.Add(new ResourceLookupKey(reference, candidate));
            }
            return list;
        }
    }
}
